script.setup:
// python-sgp4 propagated seven satellites from their TLEs into an Earth-fixed frame
// (recipe sgp4.ground-tracks → tracks.json). The globe is procedural (graticule and
// day/night from the sun's position at that time); orbits and ground tracks come from the file.
const data = await (await fetch(ctx.assets["tracks.json"])).json();
const gl = ctx.gl, steps = data.steps;
const colors = [[1, 0.78, 0.35], [0.55, 0.85, 1], [1, 0.45, 0.45], [0.55, 1, 0.6], [0.75, 0.6, 1], [1, 0.6, 0.9], [1, 1, 0.75]];
// Earth-fixed (z = north) → GL y-up.
const gp = (x, y, z) => [x, z, -y];
const lineVao = (arr) => {
  const vao = gl.createVertexArray();
  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
  gl.bufferData(gl.ARRAY_BUFFER, arr, gl.STATIC_DRAW);
  gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 4, gl.FLOAT, false, 16, 0);
  gl.bindVertexArray(null);
  return vao;
};
const sats = data.satellites.map((sat, k) => {
  const orbit = new Float32Array(steps * 4), ground = new Float32Array(steps * 4);
  for (let i = 0; i < steps; i++) {
    orbit.set([...gp(sat.xyz[i * 3], sat.xyz[i * 3 + 1], sat.xyz[i * 3 + 2]), i], i * 4);
    const lat = sat.latlon[i * 2] * Math.PI / 180, lon = sat.latlon[i * 2 + 1] * Math.PI / 180, r = 1.004;
    ground.set([...gp(r * Math.cos(lat) * Math.cos(lon), r * Math.cos(lat) * Math.sin(lon), r * Math.sin(lat)), i], i * 4);
  }
  return { name: sat.name, color: colors[k % colors.length], xyz: sat.xyz, orbit: lineVao(orbit), ground: lineVao(ground) };
});
const start = new Date(data.start);
const lineVs = `#version 300 es
layout(location=0) in vec4 a_point; uniform mat4 u_mvp; uniform float u_head; uniform float u_tail; out float v_age;
void main(){ v_age = u_head - a_point.w; gl_Position = u_mvp * vec4(a_point.xyz, 1.0); gl_PointSize = 1.0; }`;
const lineFs = `#version 300 es
precision highp float; in float v_age; out vec4 outColor; uniform vec3 u_color; uniform float u_tail; uniform float u_base;
void main(){ float a = v_age < 0.0 ? u_base * 0.6 : v_age < u_tail ? mix(1.0, u_base, v_age / u_tail) : u_base;
  outColor = vec4(u_color * a, 1.0); }`;
const globeFs = `#version 300 es
precision highp float; in vec3 v_normal; in vec3 v_pos; out vec4 outColor;
uniform vec3 u_sun; uniform vec3 u_eye; uniform float u_grid;
void main(){
  vec3 n = normalize(v_pos);
  float lat = asin(clamp(n.y, -1.0, 1.0)), lon = atan(-n.z, n.x);
  float day = smoothstep(-0.12, 0.2, dot(n, u_sun));
  vec3 ocean = mix(vec3(0.015, 0.03, 0.07), vec3(0.06, 0.16, 0.32), day);
  float step15 = radians(15.0);
  vec2 g = abs(fract(vec2(lat, lon) / step15 + 0.5) - 0.5) / fwidth(vec2(lat, lon) / step15);
  float grid = 1.0 - min(min(g.x, g.y), 1.0);
  float equator = 1.0 - min(abs(lat) / fwidth(lat) / 1.5, 1.0);
  vec3 c = ocean + vec3(0.25, 0.45, 0.7) * grid * u_grid * (0.35 + 0.65 * day) + vec3(0.6, 0.5, 0.3) * equator * 0.5;
  float rim = pow(1.0 - max(dot(n, normalize(u_eye - v_pos)), 0.0), 3.0);
  c += vec3(0.3, 0.55, 1.0) * rim * (0.25 + 0.75 * day);
  outColor = vec4(c, 1.0);
}`;
const sphere = ctx.utils.geometry.sphere(96);
Object.assign(ctx.state, {
  data, sats, start,
  globe: ctx.utils.createMesh(sphere),
  globeP: ctx.utils.createProgram(ctx.utils.MESH_VERTEX_SHADER, globeFs),
  lineP: ctx.utils.createProgram(lineVs, lineFs),
  headP: ctx.utils.createProgram(`#version 300 es
uniform mat4 u_mvp; uniform vec3 u_p; uniform float u_px; void main(){ gl_Position = u_mvp * vec4(u_p, 1.0); gl_PointSize = u_px; }`, `#version 300 es
precision highp float; out vec4 outColor; uniform vec3 u_color;
void main(){ vec2 q = gl_PointCoord * 2.0 - 1.0; float d = dot(q, q); if (d > 1.0) discard; outColor = vec4(mix(u_color, vec3(1.0), exp(-d * 6.0)) * (1.0 - d * 0.6), 1.0); }`),
  emptyVao: gl.createVertexArray(),
  camera: ctx.utils.createOrbitCamera({ distance: 7.5, theta: 0.9, phi: 1.15 }),
  overlay: new OffscreenCanvas(1, 1), tex: gl.createTexture(),
  over: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor; uniform sampler2D u_tex;
void main(){ outColor = texture(u_tex, vec2(v_uv.x, 1.0 - v_uv.y)); }`),
  bg: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
float h(vec2 p){ vec3 q = fract(vec3(p.xyx) * 0.1031); q += dot(q, q.yzx + 33.33); return fract((q.x + q.y) * q.z); }
void main(){ vec2 g = floor(v_uv * vec2(400.0, 225.0)); float s = step(0.997, h(g)) * h(g + 7.0);
  outColor = vec4(vec3(0.01, 0.012, 0.025) + s * 0.45, 1.0); }`),
});
ctx.state.o2d = ctx.state.overlay.getContext("2d");
ctx.publish("satellites", sats.length);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, { mat4 } = ctx.utils, [w, h] = ctx.resolution;
const steps = s.data.steps, dtMin = s.data.step_s / 60;
const head = (ctx.time * u.u_speed / dtMin) % (steps - 1);
const now = new Date(s.start.getTime() + head * s.data.step_s * 1000);
// Sun direction (Earth-fixed) from the UTC time of day and an approximate declination.
const hours = now.getUTCHours() + now.getUTCMinutes() / 60 + now.getUTCSeconds() / 3600;
const doy = (now - Date.UTC(now.getUTCFullYear(), 0, 0)) / 864e5;
const dec = -23.44 * Math.cos(2 * Math.PI / 365 * (doy + 10)) * Math.PI / 180, slon = (12 - hours) * 15 * Math.PI / 180;
const sun = [Math.cos(dec) * Math.cos(slon), Math.sin(dec), -Math.cos(dec) * Math.sin(slon)];
s.camera.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
const view = mat4.multiply(s.camera.getViewMatrix(), mat4.fromYRotation(ctx.time * u.u_spin));
const proj = s.camera.getProjectionMatrix(w / h, 40, 0.1, 100);
const mvp = mat4.multiply(proj, view);
ctx.utils.drawFullscreen(s.bg);
gl.enable(gl.DEPTH_TEST); gl.clear(gl.DEPTH_BUFFER_BIT);
gl.useProgram(s.globeP);
ctx.utils.setStandardUniforms(s.globeP);
const eye = s.camera.getEye(), inv = mat4.fromYRotation(-ctx.time * u.u_spin);
ctx.utils.setUniforms(s.globeP, { u_mvp: mvp, u_model: mat4.identity(), u_sun: sun, u_eye: mat4.transformPoint(inv, eye) });
s.globe.draw();
gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE); gl.depthMask(false);
gl.useProgram(s.lineP);
const tail = u.u_tail / dtMin;
// WebGL lines are 1 px; two passes shifted by a pixel make them read at full resolution.
for (const shift of [[0, 0], [2 / w, 2 / h]]) {
  const shifted = mat4.multiply(mat4.fromTranslation(shift[0], shift[1], 0), mvp);
  for (const sat of s.sats) {
    for (const [vao, base] of [[sat.orbit, 0.4], [sat.ground, 0.3]]) {
      ctx.utils.setUniforms(s.lineP, { u_mvp: shifted, u_head: head, u_tail: tail, u_color: sat.color, u_base: base });
      gl.bindVertexArray(vao);
      gl.drawArrays(gl.LINE_STRIP, 0, Math.floor(head) + 1);
      ctx.utils.setUniforms(s.lineP, { u_base: base * 0.3 });
      gl.drawArrays(gl.LINE_STRIP, Math.floor(head), steps - Math.floor(head));
    }
  }
}
gl.depthMask(true); gl.disable(gl.BLEND);
// Satellite heads and labels.
gl.useProgram(s.headP);
gl.bindVertexArray(s.emptyVao);
const L = s.o2d;
if (s.overlay.width !== w || s.overlay.height !== h) { s.overlay.width = w; s.overlay.height = h; }
L.clearRect(0, 0, w, h);
L.font = `600 ${Math.round(h / 48)}px ui-sans-serif, system-ui, sans-serif`; L.textBaseline = "middle";
const i0 = Math.floor(head), f = head - i0;
for (const sat of s.sats) {
  const a = sat.xyz, k = i0 * 3, j = Math.min(i0 + 1, steps - 1) * 3;
  const p = [0, 1, 2].map((c) => a[k + c] * (1 - f) + a[j + c] * f), gpos = [p[0], p[2], -p[1]];
  ctx.utils.setUniforms(s.headP, { u_mvp: mvp, u_p: gpos, u_color: sat.color, u_px: h / 70 });
  gl.drawArrays(gl.POINTS, 0, 1);
  const c = mat4.transformPoint(view, gpos), hidden = (() => { // behind the globe as seen from the eye?
    const e = mat4.transformPoint(inv, eye), d = gpos.map((v, n) => v - e[n]), len = Math.hypot(...d), dir = d.map((v) => v / len);
    const b = e.reduce((acc, v, n) => acc + v * dir[n], 0), cc = e.reduce((acc, v) => acc + v * v, 0) - 1, disc = b * b - cc;
    return disc > 0 && -b - Math.sqrt(disc) > 0 && -b - Math.sqrt(disc) < len;
  })();
  const clip = mat4.transformPoint(proj, c);
  if (c[2] < 0 && !hidden) {
    const x = (clip[0] * 0.5 + 0.5) * w, y = (0.5 - clip[1] * 0.5) * h;
    L.fillStyle = `rgba(${sat.color.map((v) => Math.round(v * 255)).join(",")},0.95)`;
    L.fillText(sat.name, x + h / 60, y);
  }
}
L.fillStyle = "rgba(255,255,255,0.7)"; L.textBaseline = "top";
L.fillText(now.toISOString().slice(0, 16).replace("T", " ") + " UTC", h / 40, h / 40);
gl.bindVertexArray(null);
gl.disable(gl.DEPTH_TEST);
gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
gl.bindTexture(gl.TEXTURE_2D, s.tex);
gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true);
gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, s.overlay);
gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
gl.useProgram(s.over);
ctx.utils.bindTexture(s.over, "u_tex", s.tex, 0);
ctx.utils.drawFullscreen(s.over);
gl.disable(gl.BLEND);
